#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bilnov - FIX tactile v3 (definitif) : supprime le pinch FitView maison (cause du gel), passe aux Pointer Events + machine a etats (1 pointeur = curseur / plan fixe ; >=2 = navigation NATIVE de dxf-viewer). Annule le tap au 2e doigt, curseur fige mais visible, mesure en cours preservee, reprise apres relachement total. A appliquer sur le repo courant (script 14 deploye)."""
import base64, os, sys, subprocess
EDITS=[["src/components/CadViewer.tsx", "effect", "bmF2aWdhdGlvbiBOQVRJVkU=", "", ""], ["src/components/CadViewer.tsx", "layer", "PGRpdiByZWY9e2NvbnRhaW5lclJlZn0gY2xhc3NOYW1lPSJmbGU=", "", "ICAgICAgICA8ZGl2IHJlZj17Y29udGFpbmVyUmVmfSBjbGFzc05hbWU9ImZsZXgtMSBiZy13aGl0ZSIgc3R5bGU9e3sgY3Vyc29yOiB0b29sID09PSAncGFuJyA/ICdkZWZhdWx0JyA6ICdjcm9zc2hhaXInIH19IC8+"], ["src/components/CadViewer.tsx", "refs", "U1VQUFJfVE9VQ0hfUkVGUw==", "", ""]]
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:]); print("== Bilnov - fix tactile v3 (pointer events, fin du gel) ==")
    cache={}
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read(); marker,old,new=d(dm),d(o),d(nw)
        if marker in src and old not in src: print("  = deja",name); cache[p]=src; continue
        if old not in src: print("!! ANCRE KO:",name); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; print("  ~ patche",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Fix tactile v3 applique. Aucun git push.")
if __name__=='__main__': main()
